                 (Z_to_bv 64 (s_n s)) (Z_to_bv 64 (usp + -2128)) (Z_to_bv 64 (l_T (lay Σ) + 208))
                 (Z_to_bv 64 (s_mb s + 6128)) (Z_to_bv 64 0x100000)
                 s7 s8 s9 s10 s11 t3' t4' t5' t6') F (Z_to_bv 64 qenq_entry) fc None m' (seg_rom asegs)
